 namespace Pterodactyl\Services\Dezerx\DiscordBot\Views; use Illuminate\Support\Collection; use Pterodactyl\Models\Dezerx\DiscordBotAlert; use Pterodactyl\Services\Dezerx\DiscordBot\Ui; use Pterodactyl\Services\Dezerx\DiscordBot\Style; use Pterodactyl\Services\Dezerx\DiscordBot\Format; use Pterodactyl\Services\Dezerx\DiscordBot\Servers; use Pterodactyl\Services\Dezerx\DiscordBot\BotConfig; use Pterodactyl\Services\Dezerx\DiscordBot\ResourceImage; class Alerts { public const LABELS = ['cpu' => 'CPU', 'memory' => 'RAM', 'disk' => 'Disk']; public static function list(Collection $alerts, ?string $notice = null): array { $lines = []; foreach ($alerts->take(15) as $alert) { $lines[] = self::describe($alert); } $options = $alerts->take(25)->map(fn (DiscordBotAlert $alert) => Ui::option( 'alert-' . $alert->id, $alert->server?->name ?? 'Server #' . $alert->server_id, self::thresholds($alert, false), ))->all(); return Ui::message([ Ui::container([ $notice === null ? null : Ui::text($notice), Ui::section([ '## Alerts in this Discord', $alerts->isEmpty() ? 'Nothing is being watched here yet. Add one with `/alerts add server:` and pick a role to ping.' : $alerts->count() . ' ' . ($alerts->count() === 1 ? 'server is' : 'servers are') . ' being watched. Checked every minute.', ], Ui::thumbnail(Style::current()->logo(BotConfig::panelLogo()))), $lines === [] ? null : Ui::divider(), $lines === [] ? null : Ui::text(implode("\n\n", $lines)), $options === [] ? null : Ui::row([Ui::select('dzb:alx', 'Stop watching a server…', $options)]), ], Style::current()->accent()), ]); } public static function mention(DiscordBotAlert $alert): ?string { if ($alert->role_id === null) { return null; } return self::everyone($alert) ? '@everyone' : '<@&' . $alert->role_id . '>'; } private static function everyone(DiscordBotAlert $alert): bool { return $alert->role_id !== null && (string) $alert->role_id === (string) $alert->guild_id; } private static function ping(DiscordBotAlert $alert, bool $ping): arra