reach (['memory', 'cpu', 'disk'] as $metric) { if (!isset($alert->watches()[$metric]) || $percent[$metric] === null) { continue; } $usage = $live['usage']; $detail = match ($metric) { 'memory' => Format::bytes($usage['memory']) . ' of ' . Format::megabytes($server['limits']['memory']), 'disk' => Format::bytes($usage['disk']) . ' of ' . Format::megabytes($server['limits']['disk']), default => Format::percent($usage['cpu']) . ' of ' . $server['limits']['cpu'] . '%', }; $rows[] = sprintf( '**%s** %s `%s` · %s%s', self::LABELS[$metric], Style::current()->bar($percent[$metric]), Format::percent($percent[$metric]), $detail, in_array($metric, $breaches, true) ? ' · over ' . $alert->watches()[$metric] . '%' : '', ); } $title = count($breaches) === 1 ? self::LABELS[$breaches[0]] . ' is at ' . Format::percent($percent[$breaches[0]]) : 'several limits are being hit'; return self::post($alert, $server, '🚨', Format::name($server['name']) . ': ' . $title, implode("\n", $rows), Ui::OFFLINE, true); } private static function hotImage(DiscordBotAlert $alert, array $server, array $breaches, array $percent, array $image, bool $inline): array { $style = Style::current(); [$pingLine, $roles, $everyone] = self::ping($alert, true); $over = array_map( fn (string $metric) => '**' . self::LABELS[$metric] . '** over ' . $alert->watches()[$metric] . '%', array_values(array_filter($breaches, fn (string $metric) => isset($alert->watches()[$metric]))), ); $title = count($breaches) === 1 ? self::LABELS[$breaches[0]] . ' is at ' . Format::percent($percent[$breaches[0]]) : 'several limits are being hit'; $message = Ui::message([ $pingLine, Ui::container([ Ui::text('## 🚨 ' . Format::name($server['name']) . ': ' . $title . ($over === [] ? '' : "\n" . implode(' · ', $over))), ['type' => 12, 'items' => [['media' => ['url' => $inline ? 'data:image/png;base64,' . base64_encode($image['data']) : 'attachment://' . ResourceImage::FILENAME]]]], Ui::text('-# ' . $style->footer() . ' · ' . Format::timestamp(now(